+    Q_OBJECT
+public:
+    DetachableTabWidget(QWidget * parent = nullptr);
+
+    QString tabBasename() const;
+
+protected:
+
+    void setTabBasename(QString newName);
+
+protected slots:
+
+    virtual void moveTab(int from, int to);
